/// The KMS refusal of the queue's key, as this operation's own modelled error.
///
/// Each class answers with the code KMS answers it with — the `awsQueryError` codes the
/// model carries for these shapes (`KMS.NotFoundException`, `KMS.DisabledException`,
/// `KMS.InvalidStateException`, `KMS.InvalidKeyUsageException`,
/// `KMS.AccessDeniedException`) — carrying the message KMS words that refusal in.
fn kms_refusal(refusal: sqs::encryption::KeyRefusal) -> ReceiveMessageError {
    use sqs::encryption::KeyRefusal;
    match refusal {
        KeyRefusal::NotFound(message) => ReceiveMessageErrorModeled::KmsNotFound(KmsNotFound {
            message: Some(message),
        }),
        KeyRefusal::Disabled(message) => ReceiveMessageErrorModeled::KmsDisabled(KmsDisabled {
            message: Some(message),
        }),
        KeyRefusal::InvalidState(message) => {
            ReceiveMessageErrorModeled::KmsInvalidState(KmsInvalidState {
                message: Some(message),
            })
        }
        KeyRefusal::InvalidKeyUsage(message) => {
            ReceiveMessageErrorModeled::KmsInvalidKeyUsage(KmsInvalidKeyUsage {
                message: Some(message),
            })
        }
        KeyRefusal::AccessDenied(message) => {
            ReceiveMessageErrorModeled::KmsAccessDenied(KmsAccessDenied {
                message: Some(message),
            })
        }
    }
    .into()
}

/// Refuse a name neither of this operation's system-attribute name members accepts.
///
/// Both carry one value set: `MessageSystemAttributeNames` takes the message system
/// attribute names, and `AttributeNames` is the discontinued alias of that member, so it
/// takes the same ones. Applied here rather than at the boundary because the alias's
/// modelled target is the queue attribute enum, which names none of them (see the
/// `skip_validation` note on `ReceiveMessageInput`), and applying it once keeps the two
/// spellings from answering the same request differently. The refusal names the member
/// the caller actually supplied and the set it accepts, which is the whole fix.
fn check_system_attribute_names(
    member: &str,
    requested: &[String],
) -> Result<(), ReceiveMessageError> {
    for name in requested {
        // Membership is the generated value set; the refusal states the set in the order
        // the model publishes it (`sqs::MESSAGE_SYSTEM_ATTRIBUTE_NAMES`).
        if !MESSAGE_SYSTEM_ATTRIBUTE_NAME_VALUES.contains(&name.as_str()) {
            return Err(Scaffolded::invalid_parameter_value(sqs::invalid_parameter_message(
                &format!("({name})"),
                member,
                &format!(
                    "Must be one of: {}.",
                    sqs::MESSAGE_SYSTEM_ATTRIBUTE_NAMES.join(", ")
                ),
            )));
        }
    }
    Ok(())
}

/// One stored message as this operation hands it over, under the receipt handle
/// `receipt_handle` and filtered to what the request selects.
///
/// Both ways a message is handed over — a fresh delivery and a retry replaying the batch
/// one `ReceiveRequestAttemptId` already served — project the wire message from the
/// stored one here, so the two cannot drift on what a receive reports.
fn wire_message(
    message: &sqs::StoredMessage,
    receipt_handle: String,
    system_requested: &[String],
    attribute_requested: &[String],
) -> Message {
    let attributes = system_attributes(message, system_requested);
    // The digest covers the attributes this answer RETURNS, which is what an SDK
    // verifies it against; a request that selects a subset therefore gets the digest of
    // that subset, not of the stored set.
    let message_attributes: BTreeMap<String, MessageAttributeValue> = message
        .message_attributes
        .iter()
        .filter(|(name, _)| selects(attribute_requested, name))
        .map(|(name, value)| (name.clone(), value.clone()))
        .collect();
    Message {
        message_id: Some(message.message_id.clone()),
        receipt_handle: Some(receipt_handle),
        md5_of_body: Some(message.md5_of_body.clone()),
        body: Some(message.body.clone()),
        attributes: (!attributes.is_empty()).then(|| attributes.into_iter().collect()),
        md5_of_message_attributes: sqs::md5_of_message_attributes(&message_attributes),
        message_attributes: (!message_attributes.is_empty())
            .then(|| message_attributes.into_iter().collect()),
    }
}

/// The message system attributes this emulator holds, filtered to the ones `requested`
/// selects.
///
/// Only the attributes the emulator genuinely records are reported: `SenderId`,
/// `SentTimestamp`, `ApproximateReceiveCount`, `ApproximateFirstReceiveTimestamp`, the
/// `AWSTraceHeader` a send carried in `MessageSystemAttributes` and, for a message that
/// carries them, `MessageGroupId`, `MessageDeduplicationId`, `SequenceNumber` and the
/// `DeadLetterQueueSourceArn` a redrive stamped on it. The rest of the
/// `MessageSystemAttributeName` set belongs to behaviour that is not implemented, so it is
/// omitted rather than invented.
fn system_attributes(
    message: &sqs::StoredMessage,
    requested: &[String],
) -> BTreeMap<String, String> {
    let mut attributes = BTreeMap::new();
    let mut offer = |name: &str, value: String| {
        if selects(requested, name) {
            attributes.insert(name.to_string(), value);
        }
    };
    // "SenderId — For a user, returns the user ID ... For an IAM role, returns the IAM
    // role ID": who the send this message arrived on spoke for, stamped at enqueue time.
    // A message whose sender could not be resolved carries none, and reports none rather
    // than an empty attribute.
    if !message.sender_id.is_empty() {
        offer("SenderId", message.sender_id.clone());
    }
    offer("SentTimestamp", sqs::epoch_millis(message.sent_at));
    offer(
        "ApproximateReceiveCount",
        message.receive_count.to_string(),
    );
    if let Some(first) = message.first_received_at {
        offer("ApproximateFirstReceiveTimestamp", sqs::epoch_millis(first));
    }
    // What the send stored in `MessageSystemAttributes`: "AWSTraceHeader - Returns the
    // X-Ray trace header string", reported under the name it was sent under and only
    // for a message whose send carried it.
    for (name, value) in &message.message_system_attributes {
        if let Some(string_value) = &value.string_value {
            offer(name, string_value.clone());
        }
    }
    // The three a FIFO send records. "The MessageDeduplicationId is available to the
    // consumer of the message", and a consumer of several interleaved streams needs the
    // group each message belongs to.
    if let Some(group_id) = &message.message_group_id {
        offer("MessageGroupId", group_id.clone());
    }
    if let Some(deduplication_id) = &message.message_deduplication_id {
        offer("MessageDeduplicationId", deduplication_id.clone());
    }
    if let Some(sequence_number) = &message.sequence_number {
        offer("SequenceNumber", sequence_number.clone());
    }
    // Where a redrive moved this message FROM: the ARN of the queue whose `RedrivePolicy`
    // drove it to the dead-letter queue holding it. Only a message a redrive moved carries
    // one, so only those report it — a message sent straight to this queue has no
    // dead-letter source to name.
    if let Some(source_arn) = &message.dead_letter_source_arn {
        offer("DeadLetterQueueSourceArn", source_arn.clone());
    }
    attributes
}

