    // receive's, so the bound on what a queue remembers stays in one place.
    queue.record_receive_attempt(
        attempt_id.to_string(),
        sqs::ReceiveAttempt {
            served_at: attempt.served_at,
            delivered: attempt
                .delivered
                .iter()
                .map(|handed| sqs::DeliveredMessage {
                    invisible_until,
