/// Answer a retry under a `ReceiveRequestAttemptId` with the batch that token already
/// handed over, resetting those messages' visibility timeout.
fn replay_attempt(
    queue: &mut sqs::Queue,
    attempt_id: &str,
    attempt: &sqs::ReceiveAttempt,
    invisible_until: SystemTime,
    request: &ReceiveRequest,
    now: SystemTime,
) -> Result<ReceiveMessageOutput, ReceiveMessageError> {
    // The retry is served only "if none of the messages have been
    // modified (deleted or had their visibility changes)". The refusal
    // carries the sender fault Amazon SQS answers a refused parameter
    // with, in that fault's own template — the token this request
    // supplied, the parameter it was supplied for, and the `Reason:`
    // clause stating the rule, which is what tells the caller to
    // re-receive instead of retrying this token.
    if queue.receive_attempt_was_modified(attempt) {
        return Err(crate::scaffolded::Scaffolded::invalid_parameter_value(
            sqs::invalid_parameter_message(
                attempt_id,
                "ReceiveRequestAttemptId",
                sqs::RECEIVE_ATTEMPT_NOT_RETRYABLE,
            ),
        ));
    }
    let mut delivered = Vec::with_capacity(attempt.delivered.len());
    for handed in &attempt.delivered {
        let Some(message) = queue
            .messages
            .iter_mut()
            .find(|message| message.message_id == handed.message_id)
        else {
            continue;
        };
        // The retry is the same receive, so it hands the message over
        // again without counting as another delivery — it only resets the
        // visibility timeout.
        message.invisible_until = Some(invisible_until);
        delivered.push(wire_message(
            message,
            handed.receipt_handle.clone(),
            &request.system_requested,
            &request.attribute_requested,
        ));
    }
    // What this retry left the batch at, so a further one still
    // recognises it as unmodified. The window keeps running from the
    // receive that minted the token, which is the action it is "5 minutes
    // after". Written through the recording method, like the first
    // receive's, so the bound on what a queue remembers stays in one place.
    queue.record_receive_attempt(
        attempt_id.to_string(),
        sqs::ReceiveAttempt {
            served_at: attempt.served_at,
            delivered: attempt
                .delivered
                .iter()
                .map(|handed| sqs::DeliveredMessage {
                    invisible_until,
                    ..handed.clone()
                })
                .collect(),
        },
    );
    // A retry hands the same messages over again: no further delivery of
    // them is counted against the messages themselves, but the consumer was
    // handed them, which is what the `AWS/SQS` received counter counts.
    queue.count_traffic(
        sqs::QueueTraffic::MessagesReceived,
        sqs::count_as_f64(delivered.len()),
        now,
    );
    Ok(ReceiveMessageOutput {
        messages: Some(delivered),
    })
}
