import re
macro = '''
/// Defines `kms_refusal` for an operation: the refusal of the queue's key, as that
/// operation's own modelled error.
///
/// Each class answers with the code KMS answers it with — the `awsQueryError` codes the
/// model carries for these shapes (`KMS.NotFoundException`, `KMS.DisabledException`,
/// `KMS.InvalidStateException`, `KMS.InvalidKeyUsageException`,
/// `KMS.AccessDeniedException`) — carrying the message KMS words that refusal in.
///
/// A macro because every operation that touches a queue's key models the same five
/// shapes in an enum of its own, so one function cannot name them all.
macro_rules! define_kms_refusal {
    ($modeled:ident, $error:ident) => {
        fn kms_refusal(refusal: $crate::state::encryption::KeyRefusal) -> $error {
            use $crate::state::encryption::KeyRefusal;
            match refusal {
                KeyRefusal::NotFound(message) => $modeled::KmsNotFound(KmsNotFound {
                    message: Some(message),
                }),
                KeyRefusal::Disabled(message) => $modeled::KmsDisabled(KmsDisabled {
                    message: Some(message),
