cat > src/state/send_rules.rs <<'EOF'
// SPDX-License-Identifier: CC0-1.0

//! The member rules a `SendMessage` and every `SendMessageBatch` entry are judged by.
//!
//! The two operations word a refusal differently (an error for the whole call, or a
//! `Failed` entry under its own `Id`) and order their checks differently, so each rule here
//! answers with a [`SendFault`] and leaves the wording of the channel to the caller. What
//! counts as a fault is stated once.

use super::*;
use crate::scaffolded::{Scaffolded, INVALID_PARAMETER_VALUE, MISSING_PARAMETER};

/// A member of a send that the request got wrong, before it is worded for the call that
/// carries it.
#[derive(Debug, PartialEq, Eq)]
pub enum SendFault {
    /// The request had to carry this parameter and did not.
    Missing(&'static str),
    /// A value the parameter does not accept, with the sentence saying why.
    Invalid(String),
}

impl SendFault {
    /// The code and message a batch result entry reports this fault under.
    pub fn entry_code_and_message(self) -> (&'static str, String) {
        match self {
            Self::Missing(parameter) => (MISSING_PARAMETER, missing_parameter_message(parameter)),
            Self::Invalid(reason) => (INVALID_PARAMETER_VALUE, reason),
        }
    }
}

/// Lets a handler refuse the whole call with `?` or `.into()`.
impl<E> From<SendFault> for Scaffolded<E> {
    fn from(fault: SendFault) -> Self {
        match fault {
            SendFault::Missing(parameter) => Self::missing_parameter(parameter),
            SendFault::Invalid(reason) => Self::invalid_parameter_value(reason),
        }
    }
}

/// Judge `MessageGroupId`.
///
/// "In FIFO queues, MessageGroupId organizes messages into distinct groups ... If you do
/// not provide a MessageGroupId when sending a message to a FIFO queue, the action fails."
/// A standard queue may carry one too ("In standard queues, using MessageGroupId enables
/// fair queues"), where it identifies a tenant and orders nothing.
pub fn message_group_fault(group_id: Option<&str>, fifo: bool) -> Option<SendFault> {
    match group_id {
        Some(given) => message_token_refusal("MessageGroupId", given).map(SendFault::Invalid),
        // Absent, not invalid: the refusal names the parameter the request had to carry.
        None if fifo => Some(SendFault::Missing("MessageGroupId")),
        None => None,
    }
}

/// The token a message is deduplicated under, on a FIFO queue: the one the request
/// supplied, or, "if you aren't able to provide a MessageDeduplicationId and you enable
/// ContentBasedDeduplication for your queue", a SHA-256 hash of the body. "If you don't
/// provide a MessageDeduplicationId and the queue doesn't have ContentBasedDeduplication
/// set, the action fails with an error." A standard queue takes no token at all.
pub fn deduplication_id(
    given: Option<&str>,
    body: &str,
    queue: &Queue,
) -> Result<Option<String>, SendFault> {
    let fifo = queue.is_fifo();
    match given {
        Some(given) => {
            if !fifo {
                return Err(SendFault::Invalid(invalid_parameter_message(
                    given,
                    "MessageDeduplicationId",
                    QUEUE_TYPE_PARAMETER_REASON,
                )));
            }
            match message_token_refusal("MessageDeduplicationId", given) {
                Some(reason) => Err(SendFault::Invalid(reason)),
                None => Ok(Some(given.to_string())),
            }
        }
        None if fifo && queue.content_based_deduplication() => {
            Ok(Some(content_deduplication_token(body)))
        }
        None if fifo => Err(SendFault::Invalid(NO_DEDUPLICATION_ID.to_string())),
        None => Ok(None),
    }
}

/// Judge the delay a message ends up with, whether the request named one or the queue's own
/// value applies: it must be inside the range the model documents for `DelaySeconds`.
pub fn delay_fault(delay: i64) -> Option<SendFault> {
    let (min, max) = integer_bounds(DELAY_SECONDS);
    (delay < min || delay > max).then(|| {
        SendFault::Invalid(invalid_parameter_message(
            &delay.to_string(),
            DELAY_SECONDS,
            &format!("{DELAY_SECONDS} must be >= {min} and <= {max}."),
        ))
    })
}

/// Judge the message attributes a send carries: how many, then each one's own form.
pub fn message_attributes_fault(
    attributes: &BTreeMap<String, MessageAttributeValue>,
) -> Option<SendFault> {
    if attributes.len() > MAX_MESSAGE_ATTRIBUTES {
        return Some(SendFault::Invalid(format!(
            "Number of message attributes [{}] exceeds the allowed maximum [{MAX_MESSAGE_ATTRIBUTES}].",
            attributes.len(),
        )));
    }
    // Name-ordered, so a message with two bad attributes is always refused for the same one.
    attributes
        .iter()
        .find_map(|(name, value)| message_attribute_refusal(name, value))
        .map(SendFault::Invalid)
}
