/// The queue a task moves its messages to: the one the request named, or, when it left the
/// field blank, the queue that drives its messages to the source.
fn resolve_destination(
    state: &sqs::ComAmazonawsSqsAmazonsqsState,
    region: &str,
    named_destination: Option<String>,
    dead_letter_sources: &[String],
) -> Result<String, StartMessageMoveTaskError> {
    match named_destination {
        Some(name) if state.holds_queue(region, &name) => name,
        Some(_) => {
            return Err(StartMessageMoveTaskErrorModeled::ResourceNotFoundException(
                sqs::resource_not_found("DestinationArn"),
            )
            .into())
        }
        None if dead_letter_sources.len() == 1 => dead_letter_sources[0].clone(),
        None => {
            return Err(StartMessageMoveTaskErrorModeled::UnsupportedOperation(
                UnsupportedOperation {
                    message: Some(format!(
