            use $crate::state::authorization::PolicyRefusal;
            match refusal {
                PolicyRefusal::Document(error) => $modeled::InvalidAttributeValue(error).into(),
                PolicyRefusal::ActionName(message) => {
                    $crate::scaffolded::Scaffolded::invalid_parameter_value(message)
                }
